import{_ as e,o as a,c as l,a2 as n}from"./chunks/framework.BEmfQga0.js";const c=JSON.parse('{"title":"Plugins","description":"","frontmatter":{},"headers":[],"relativePath":"platform-concepts/plugins.md","filePath":"platform-concepts/plugins.md","lastUpdated":1788258471000}'),i={name:"platform-concepts/plugins.md"};function r(s,t,o,d,g,p){return a(),l("div",null,[...t[0]||(t[0]=[n('<h1 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h1><p>Plugins are <strong>reusable agent capabilities</strong> that run on the LightRSI platform. Each plugin provides one well-scoped capability — context management, memory, or future features — and works across all supported hosts.</p><h2 id="plugin-model" tabindex="-1">Plugin Model <a class="header-anchor" href="#plugin-model" aria-label="Permalink to &quot;Plugin Model&quot;">​</a></h2><p>A plugin is a self-contained package with:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Component</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Manifest</strong></td><td style="text-align:left;">Metadata: ID, version, compatible hosts, permissions needed</td></tr><tr><td style="text-align:left;"><strong>Configuration schema</strong></td><td style="text-align:left;">Declares what settings the plugin accepts, with types and defaults</td></tr><tr><td style="text-align:left;"><strong>Lifecycle hooks</strong></td><td style="text-align:left;">Functions called by the runtime at specific points (install, enable, disable, etc.)</td></tr><tr><td style="text-align:left;"><strong>Runtime logic</strong></td><td style="text-align:left;">The actual behavior: intercepting messages, transforming context, managing state</td></tr></tbody></table><h2 id="current-plugins" tabindex="-1">Current Plugins <a class="header-anchor" href="#current-plugins" aria-label="Permalink to &quot;Current Plugins&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Plugin</th><th style="text-align:left;">Capability</th><th style="text-align:left;">Status</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/LightRSI/plugin-catalog/tokenpilot/overview">TokenPilot</a></td><td style="text-align:left;">Cache-aware context management</td><td style="text-align:left;">Stable</td></tr></tbody></table><p>TokenPilot currently provides full host integrations for OpenClaw, Codex, and Claude Code. A narrower DeepSeek Harness compatibility adapter is maintained separately.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/LightRSI/platform-concepts/plugin-lifecycle">Plugin Lifecycle</a> — the state machine</li><li><a href="/LightRSI/plugin-catalog/tokenpilot/overview">TokenPilot Overview</a> — see a real plugin</li><li><a href="/LightRSI/plugin-development/build-your-first-plugin">Build Your First Plugin</a> — start developing</li></ul>',10)])])}const h=e(i,[["render",r]]);export{c as __pageData,h as default};
